/* IronStack push service worker — used in development when next-pwa is disabled.
 * Source of truth for push handlers: worker/index.js (merged into production SW).
 * After a production build, public/sw.js is regenerated by @ducanh2912/next-pwa.
 * To restore this file for local push testing: copy from worker/index.js or re-checkout.
 */

self.addEventListener('push', (event) => {
  let data = { title: 'IRONSTACK', body: '', link: '/dashboard/home' }
  try {
    if (event.data) {
      data = { ...data, ...event.data.json() }
    }
  } catch {
    try {
      const text = event.data?.text()
      if (text) data.body = text
    } catch {
      /* ignore */
    }
  }

  event.waitUntil(
    self.registration.showNotification(data.title || 'IRONSTACK', {
      body: data.body || '',
      icon: '/icons/icon-192x192.png',
      badge: '/icons/icon-192x192.png',
      data: { link: data.link || '/dashboard/home' },
    }),
  )
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const link =
    (event.notification.data && event.notification.data.link) ||
    '/dashboard/home'
  const url = new URL(link, self.location.origin).href

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(
      (clients) => {
        for (const client of clients) {
          if ('focus' in client && client.url.startsWith(self.location.origin)) {
            client.navigate(url)
            return client.focus()
          }
        }
        if (self.clients.openWindow) {
          return self.clients.openWindow(url)
        }
        return undefined
      },
    ),
  )
})
